/*
 * facet skeuo theme: a physical key with a base, a face that sinks when pressed, and a highlight.
 * Colors come from the shadcn semantic tokens (--primary, --secondary, ...); the material comes
 * from the --mat-* tokens below. Light and dark differ only in internal --skeuo-* values, so
 * overriding --mat-* (e.g. from a parameter panel) works in both color schemes.
 *
 * The component sets the frame (height, padding, gap, font size). The key is drawn inside it:
 * the face covers the top of the frame, the base shows below it by --mat-depth, and pressing
 * moves the face down. The face surface is the face slot's ::before, positioned against the
 * button, so it fills the frame whatever size or className the button gets.
 * Import it from the CSS entry that has `@import "tailwindcss"` so @variant resolves.
 */
@layer components {
  [data-theme="skeuo"] {
    /* Material tokens: the public knobs of this theme. */
    --mat-depth: 4px;
    --mat-rim: 22%;
    --mat-gloss: 12%;
    --mat-highlight: 0.35;
    --mat-shadow: 6px;

    /* MARK: Button */
    .cn-button {
      /* Scheme-dependent internals. They sit on the button and switch through the `dark`
         variant, so dark mode follows the same rule as the base theme. */
      --skeuo-shadow: oklch(0.2 0.02 260 / 0.28);
      --skeuo-shadow-pressed: oklch(0.2 0.02 260 / 0.24);
      --skeuo-highlight-scale: 1;
      --skeuo-hover: brightness(1.06);
      --skeuo-ring: color-mix(in oklab, var(--ring), var(--foreground) 55%);
      /* Darkened (light) or dark text (dark) so the label keeps 4.5:1 on the face. */
      --skeuo-destructive-face: color-mix(
        in oklab,
        var(--destructive),
        #000 32%
      );
      --skeuo-destructive-on: oklch(0.985 0 0);

      @variant dark {
        --skeuo-shadow: oklch(0 0 0 / 0.7);
        --skeuo-shadow-pressed: oklch(0 0 0 / 0.6);
        --skeuo-highlight-scale: 0.55;
        --skeuo-hover: brightness(1.12);
        --skeuo-ring: color-mix(in oklab, var(--ring), var(--foreground) 65%);
        --skeuo-destructive-face: var(--destructive);
        --skeuo-destructive-on: oklch(0.145 0 0);
      }

      --skeuo-depth: var(--mat-depth);
      /* How far the face has sunk; set while pressed. */
      --skeuo-press: 0px;
      /* The face's 1px rim. Variants without a face color replace it. */
      --skeuo-edge: inset 0 0 0 1px
        var(
          --skeuo-rim,
          color-mix(
            in oklab,
            var(--skeuo-face),
            #000 calc(var(--mat-rim) * 0.6)
          )
        );

      position: relative;
      isolation: isolate;
      border-color: transparent;
      border-radius: 8px;
      font-weight: 500;
      color: var(--skeuo-on);
      outline: none;

      /* The ring is drawn with box-shadow; forced-colors mode drops it, so it gets an outline. */
      &:focus-visible {
        box-shadow:
          0 0 0 2px var(--background),
          0 0 0 4px var(--skeuo-ring);
      }

      &[aria-invalid="true"] {
        --skeuo-ring: var(--destructive);
        box-shadow:
          0 0 0 2px var(--background),
          0 0 0 4px color-mix(in oklab, var(--destructive) 45%, transparent);
      }

      &[aria-invalid="true"]:focus-visible {
        box-shadow:
          0 0 0 2px var(--background),
          0 0 0 4px var(--skeuo-ring);
      }

      @media (forced-colors: active) {
        &:focus-visible {
          outline: 2px solid CanvasText;
          outline-offset: 2px;
        }
      }

      &:disabled {
        opacity: 0.5;
      }

      @variant hover {
        & .cn-button-face::before {
          filter: var(--skeuo-hover);
        }
      }

      &:active:not([aria-haspopup]) {
        --skeuo-press: max(0px, var(--skeuo-depth) - 1px);

        & .cn-button-base {
          box-shadow: 0 1px 2px var(--skeuo-shadow-pressed);
        }
      }
    }

    /* The slots are positioned against the button's padding box; -1px reaches over its border. */
    .cn-button-base {
      position: absolute;
      inset: calc(var(--skeuo-depth) - 1px) -1px -1px;
      border-radius: inherit;
      background: var(
        --skeuo-base,
        color-mix(in oklab, var(--skeuo-face), #000 var(--mat-rim))
      );
      box-shadow: 0 calc(var(--skeuo-depth) * 0.5 + 1px) var(--mat-shadow)
        var(--skeuo-shadow);
      transition: box-shadow 80ms ease-out;
    }

    .cn-button-face {
      display: contents;
      border-radius: inherit;
      gap: inherit;

      &::before {
        content: "";
        position: absolute;
        inset: -1px -1px calc(var(--skeuo-depth) - 1px);
        border-radius: inherit;
        background: linear-gradient(
          180deg,
          color-mix(in oklab, var(--skeuo-face), #fff var(--mat-gloss)),
          var(--skeuo-face)
        );
        box-shadow: var(--skeuo-edge);
        translate: 0 var(--skeuo-press);
        transition:
          translate 80ms ease-out,
          filter 150ms ease-out,
          box-shadow 80ms ease-out;
      }
    }

    .cn-button-highlight {
      position: absolute;
      inset: 0 0 auto;
      height: calc((100% - var(--skeuo-depth)) * 0.48);
      border-radius: inherit;
      border-bottom-right-radius: 0;
      border-bottom-left-radius: 0;
      background: linear-gradient(
        180deg,
        rgb(
          255 255 255 /
            calc(var(--mat-highlight) * var(--skeuo-highlight-scale))
        ),
        rgb(255 255 255 / 0)
      );
      translate: 0 var(--skeuo-press);
      transition: translate 80ms ease-out;
      pointer-events: none;
    }

    /* Centered on the face rather than the frame, and sinks with it. */
    .cn-button-label {
      position: relative;
      display: inline-flex;
      align-items: center;
      gap: inherit;
      translate: 0 calc(var(--skeuo-press) - var(--skeuo-depth) / 2);
      transition: translate 80ms ease-out;
    }

    /* Variants */
    .cn-button-variant-default {
      --skeuo-face: var(--primary);
      --skeuo-on: var(--primary-foreground);
    }

    .cn-button-variant-secondary {
      --skeuo-face: var(--secondary);
      --skeuo-on: var(--secondary-foreground);
    }

    .cn-button-variant-destructive {
      --skeuo-face: var(--skeuo-destructive-face);
      --skeuo-on: var(--skeuo-destructive-on);
    }

    .cn-button-variant-default,
    .cn-button-variant-destructive {
      text-shadow: 0 1px 0 rgb(0 0 0 / 0.16);
    }

    /* Outline: a shallow key with a rim and no fill color. */
    .cn-button-variant-outline {
      --skeuo-depth: calc(var(--mat-depth) * 0.5);
      --skeuo-face: var(--background);
      --skeuo-on: var(--foreground);
      --skeuo-base: color-mix(
        in oklab,
        var(--foreground) 22%,
        var(--background)
      );
      --skeuo-rim: color-mix(in oklab, var(--foreground) 20%, transparent);

      & .cn-button-highlight {
        display: none;
      }
    }

    /* Ghost and link carry no material. Link is a plain text link. */
    .cn-button-variant-ghost,
    .cn-button-variant-link {
      --skeuo-depth: 0px;
      --skeuo-edge: 0 0 #0000;

      & .cn-button-base,
      & .cn-button-highlight {
        display: none;
      }
    }

    .cn-button-variant-ghost {
      --skeuo-on: var(--foreground);

      & .cn-button-face::before {
        background: transparent;
      }

      @variant hover {
        & .cn-button-face::before {
          background: var(--muted);
          filter: none;
        }
      }

      &:active:not([aria-haspopup]) .cn-button-face::before {
        background: var(--muted);
        box-shadow: inset 0 1px 3px var(--skeuo-shadow);
      }
    }

    .cn-button-variant-link {
      --skeuo-on: var(--primary);

      & .cn-button-face::before {
        content: none;
      }

      & .cn-button-label {
        text-underline-offset: 4px;
      }

      @variant hover {
        & .cn-button-label {
          text-decoration-line: underline;
        }
      }
    }

    /* Sizes: the component owns the frame; the theme only rounds it. */
    .cn-button-size-xs,
    .cn-button-size-icon-xs {
      border-radius: 6px;
    }

    .cn-button-size-sm,
    .cn-button-size-icon-sm {
      border-radius: 7px;
    }

    .cn-button-size-lg,
    .cn-button-size-icon-lg {
      border-radius: 9px;
    }
  }

  /* Reduced motion: pressing changes only shadows, the face does not move. */
  @media (prefers-reduced-motion: reduce) {
    [data-theme="skeuo"] {
      .cn-button-face::before,
      .cn-button-base,
      .cn-button-highlight,
      .cn-button-label {
        transition: none;
      }

      .cn-button:active:not([aria-haspopup]) {
        --skeuo-press: 0px;

        & .cn-button-face::before {
          box-shadow:
            var(--skeuo-edge),
            inset 0 2px 5px var(--skeuo-shadow);
        }
      }
    }
  }
}
